"""Build the Station programming proposal. No stream or platform activation is implied."""
import json,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'public/vaccines/research-2026-11-09.json').read_text());V={v['id']:v for v in D['videos']}
run=[('uQKjI6395iU','The familiar opener','Start with the biggest retrieved catalogue video.'),('R4VTfu95HHc','The last record','Carry the audience into the Pink Carnations visual world.'),('JHJt6dBBtlQ','The band in a room','A full-song session changes the texture of the run.'),(None,'New single · planned slot','A short band introduction into the next record’s primary video. Date and asset to confirm.'),('dU9hrd35Dsg','Back to the beginning','A recognisable catalogue song after the new release.'),('KPCzMoANomA','Another scene','A visualiser with the same band and a different setting.'),('AuSap_mtIfY','The lyric moment','A proven catalogue lyric destination, not another music video.'),('84no_HITKFo','Across the eras','Another substantial catalogue entry point.'),(None,'New-song performance · planned slot','A full performance from the proposed small-room capture. Commission and rights to confirm.'),('ncS6WWSWguI','Pink Carnations, again','The album-day visualiser returns the programme to the most recent album.'),('U-AgIXURXwI','A change of pace','A short visual scene before the final catalogue destination.'),('5tr5ptnUoDE','The closing connection','Wetsuit closes this draft run; refresh the sequence as the new record arrives.')]
rows=[]
for i,(id,role,why) in enumerate(run):
 if id:
  v=V[id];im=f'/vaccines/images/{id}.jpg' if (R/f'public/vaccines/images/{id}.jpg').exists() else f'https://i.ytimg.com/vi/{id}/hqdefault.jpg'
  rows.append(f'<a class="station-item" href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener"><span class="num">{i+1:02d}</span><img src="{im}" alt="{html.escape(v["title"],quote=True)}" loading="lazy" width="160" height="90"><div><span class="tag">{role}</span><h3>{html.escape(v["title"].replace("The Vaccines - ",""))}</h3><p>{why}</p></div><span aria-hidden="true">↗</span></a>')
 else:rows.append(f'<div class="station-slot"><span class="tag">{i+1:02d} / Proposed addition · not yet available</span><h3>{role}</h3><p>{why}</p></div>')
secs=sum(V[id]['durationSec'] for id,_,_ in run if id)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="The Vaccines Station: a proposed programme connecting catalogue, live performances and the next record. Sample running order and delivery plan."><title>The Vaccines on repeat — Station proposal</title><link rel="stylesheet" href="/vaccines/deck.css"></head><body class="station-body"><a class="skip" href="#programme">Skip to the programme</a><header class="topbar"><a class="brand" href="/vaccines">The Vaccines × YouTube</a><nav aria-label="Station proposal"><a href="#programme">Running order</a><a href="#delivery">Delivery</a><a href="/vaccines">Deep dive ↗</a></nav></header><main><section class="slide wine"><div class="inner"><span class="label">Station proposal · 9 November 2026</span><div class="grid2"><div><h1 class="station-wordmark">The Vaccines<em>on repeat.</em></h1><p class="lead">The songs people know.<br>The band in the room.<br>The record that comes next.</p><p class="small mt">A programming proposal to discuss with YouTube. Access, technical setup and rights are unconfirmed; this page is not a live Station.</p><div class="actions"><a class="button" href="#programme">Explore the running order ↓</a></div></div><div><div class="station-lineup">'''+''.join(f'<img src="/vaccines/images/{id}.jpg" alt="{html.escape(V[id]["title"],quote=True)}">' for id in ['uQKjI6395iU','R4VTfu95HHc','JHJt6dBBtlQ','KPCzMoANomA'])+'''</div><p class="lead serif">Connect the eras.<br>Make space for the next one.</p><p class="small mt">Catalogue as a way in, not a wall of old hits. Alternate familiar songs with Pink Carnations visuals, performance and a clearly signposted new-release slot.</p></div></div></div></section><section class="slide" id="programme"><div class="inner"><span class="label">Sample programme · proposed sequence</span><h2>A run, not an archive.<br><span class="serif">Give each song a neighbour.</span></h2><p class="lead">Ten existing videos and two proposed new-release slots. The selected existing footage totals '''+f'{secs//60}m {secs%60:02d}s'+''' before introductions or new assets. Each existing entry opens its source video; the sequence is an editorial preview.</p><div class="station-list">'''+''.join(rows)+'''</div><p class="source">Video availability and metadata verified through the existing Watcher catalogue route on 9 November 2026. Inclusion is a programming suggestion; uploader ownership, edit rights, rebroadcast permissions, territorial restrictions and Content ID behaviour must be checked before any stream. No asset is rebroadcast from this page.</p></div></section><section class="slide blue" id="delivery"><div class="inner"><span class="label">How we make it useful</span><h2>Start with the programme.<br><span class="serif">Ask for the platform.</span></h2><div class="grid3 mt"><div class="decision"><span class="n">01 / Curate now</span><h3>A playlist first</h3><p>Build a proposed order from videos already on YouTube, add the new release when delivered, and give the playlist a channel-home shelf. VMG curates; management approves. This does not require rebroadcasting the files.</p></div><div class="decision"><span class="n">02 / Confirm access</span><h3>The Station conversation</h3><p>Ask YouTube whether the channel can access Stations and what delivery, duration, operation and reporting requirements apply. Check the rights position with management, label and relevant video partners.</p></div><div class="decision"><span class="n">03 / Refresh deliberately</span><h3>New music in the run</h3><p>Update the new-release slots as the campaign evolves. Refresh the entry point and the live selection; don’t assume a 33-minute sample can simply become a 24/7 product without programming and operational work.</p></div></div><div class="pair mt"><div class="note"><h3>Who owns it?</h3><p class="mt">VMG: proposed sequence and partner brief. Management / label: artist approval and rights map. Video partners: permissions and deliverable checks. YouTube: eligibility, setup and supported reporting.</p></div><div class="note"><h3>What would success mean?</h3><p class="mt">Use the reporting YouTube actually makes available to assess repeat viewing and the programme’s role in new-release discovery. For the playlist version, inspect playlist traffic and watch time in Studio. No uplift or audience size is assumed.</p></div></div><div class="actions"><a class="button" href="/vaccines#station">Back to the campaign deep dive</a><a class="button secondary" href="/vaccines/research-2026-11-09.json">Open source data</a></div><p class="source">Station concept informed by the CHVRCHES, IDLES and Amyl references. The Vaccines’ selected videos and sequencing are specific to this channel. No Station has been requested, activated or promised.</p></div></section></main></body></html>'''
(R/'public/vaccines/station.html').write_text(page)
print(f'Rendered Station proposal: {secs//60}:{secs%60:02d} of existing footage')
